                  </div>
                </div>
                <div className="max-h-[300px] overflow-y-auto">
                  {/* Global Chat Option */}
                  <button onClick={handleGlobalChatClick} className="w-full px-2 py-1 text-left hover:bg-gold/20">
                    <span className="text-sm">Game Chat</span>
                  </button>

                  {/* Rooms */}
                  {filteredRooms.map((room) => (
                    <button
