      cleanupExpiredEntries(tilesCache, tilesStaleMs);
      cleanupExpiredEntries(hyperstructuresCache, hyperstructuresStaleMs);
      cleanupExpiredEntries(structureExplorerDetailsCache, structureExplorerDetailsStaleMs);
    },
    10 * 60 * 1000,
