  async fetchAllTiles(): Promise<Tile[]> {
    const cacheBase = this.cacheBaseUrl?.trim();
    if (cacheBase) {
      try {
        const cacheUrl = buildCacheUrl(cacheBase, "/api/cache/tiles");
