                },
              }
            : null,
        destroyedTick: hexToBigInt(guardData.charlie_destroyed_tick),
        cooldownEnd: 0, // Will be calculated by the client
      },
      {
        slot: GuardSlot.Bravo,
        troops:
          guardData.bravo_count && hexToBigInt(guardData.bravo_count) > 0n
            ? {
