  async fetchHyperstructuresWithRealmCount(radius: number): Promise<HyperstructureRealmCountDataRaw[]> {
    const query = HYPERSTRUCTURE_QUERIES.HYPERSTRUCTURES_WITH_REALM_COUNT.replace(
